using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class OrdenDeReglasPorRelevancia
{
    private const int MaximoSeccionesConsultadas = int.MaxValue;

    private const string ConsultaQueAlcanzaLasReglas =
        "nota definitiva promedio ponderado asistencia inasistencia faltas perdida perdidas habilitacion prueba academica beca rendimiento sin registro";

    private readonly IBaseConocimiento _baseConocimiento;

    public OrdenDeReglasPorRelevancia(IBaseConocimiento baseConocimiento)
    {
        _baseConocimiento = baseConocimiento;
    }

    public IReadOnlyList<Cita> Ordenar(IReadOnlyList<Cita> bloque, string pregunta)
    {
        var raicesDeLaPregunta = RaicesDeContenido.De(pregunta).ToList();
        if (bloque.Count == 0 || raicesDeLaPregunta.Count == 0)
        {
            return bloque;
        }

        var secciones = _baseConocimiento.BuscarSecciones(ConsultaQueAlcanzaLasReglas, MaximoSeccionesConsultadas);
        return [.. bloque.OrderByDescending(cita => Relevancia(cita, secciones, raicesDeLaPregunta))];
    }

    private static int Relevancia(Cita cita, IReadOnlyList<SeccionDocumento> secciones, IReadOnlyList<string> raicesDeLaPregunta)
    {
        var seccion = secciones.FirstOrDefault(s => s.Documento == cita.Documento && s.Seccion == cita.Seccion);
        if (seccion is null)
        {
            return 0;
        }

        var raicesDeLaSeccion = RaicesDeContenido.De($"{seccion.Titulo} {seccion.Texto}").ToHashSet(StringComparer.Ordinal);
        return raicesDeLaPregunta.Count(raicesDeLaSeccion.Contains);
    }
}
using TutorFlow.Core.Academico;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public static class ReglasAplicadas
{
    public const string DocumentoReglamento = "reglamento_academico_2025.md";
    public const string DocumentoEvaluacion = "evaluacion_y_calificaciones.md";
    public const string DocumentoBienestar = "bienestar_y_becas.md";

    private static readonly IReadOnlyList<ReglaCondicionada> OrdenFijo =
    [
        new(new Cita(DocumentoEvaluacion, Textos.SeccionDefinitiva), lectura => lectura.Notas),
        new(new Cita(DocumentoEvaluacion, Textos.SeccionPromedio), lectura => lectura.Notas),
        new(new Cita(DocumentoReglamento, Textos.SeccionPerdidaPorInasistencia), lectura => lectura.Asistencia),
        new(new Cita(DocumentoBienestar, Textos.SeccionBecaPorRendimiento), lectura => lectura.Notas),
        new(new Cita(DocumentoReglamento, Textos.SeccionNotaMinima), lectura => lectura.Hay(EstadoAsignatura.Perdida)),
        new(new Cita(DocumentoReglamento, Textos.SeccionHabilitacion), lectura => lectura.Hay(EstadoAsignatura.Perdida)),
        new(new Cita(DocumentoReglamento, Textos.SeccionNoHabilitables), lectura => lectura.Hay(EstadoAsignatura.PerdidaPorInasistencia)),
        new(new Cita(DocumentoReglamento, Textos.SeccionPerdidaPorInasistencia), lectura => lectura.Hay(EstadoAsignatura.PerdidaPorInasistencia)),
        new(new Cita(DocumentoReglamento, Textos.SeccionPruebaAcademica), lectura => lectura.PruebaAcademica),
        new(new Cita(DocumentoReglamento, Textos.SeccionAsistenciaSinRegistro), lectura => lectura.AsistenciaSinRegistro),
        new(new Cita(DocumentoEvaluacion, Textos.SeccionDefinitiva), lectura => lectura.Hay(EstadoAsignatura.SinDefinitiva))
    ];

    public static IReadOnlyList<int> DeNotas(IReadOnlyList<ResumenEstudiante> resumenes) =>
        Entradas(new LecturaDeReglas(true, false, resumenes));

    public static IReadOnlyList<int> DeAsistencia(IReadOnlyList<ResumenEstudiante> resumenes) =>
        Entradas(new LecturaDeReglas(false, true, resumenes));

    public static IReadOnlyList<int> DeNotasYAsistencia(IReadOnlyList<ResumenEstudiante> resumenes) =>
        Entradas(new LecturaDeReglas(true, true, resumenes));

    public static IReadOnlyList<int> DePrograma(IReadOnlyList<ResumenEstudiante> resumenes) =>
        Entradas(new LecturaDeReglas(false, false, resumenes));

    public static IReadOnlyList<Cita> Citas(IEnumerable<int> entradas) =>
        [.. entradas.Distinct().Order().Select(entrada => OrdenFijo[entrada].Cita).Distinct()];

    private static List<int> Entradas(LecturaDeReglas lectura) =>
        [.. Enumerable.Range(0, OrdenFijo.Count).Where(entrada => OrdenFijo[entrada].Aplica(lectura))];

    private sealed record ReglaCondicionada(Cita Cita, Func<LecturaDeReglas, bool> Aplica);

    private sealed record LecturaDeReglas(bool Notas, bool Asistencia, IReadOnlyList<ResumenEstudiante> Resumenes)
    {
        private IEnumerable<ResultadoAsignatura> Resultados => Resumenes.SelectMany(resumen => resumen.Asignaturas);

        public bool PruebaAcademica => Resumenes.Any(resumen => resumen.PruebaAcademica);

        public bool AsistenciaSinRegistro => Resultados.Any(r => r.EstadoAsistencia == EstadoAsistencia.SinRegistro);

        public bool Hay(EstadoAsignatura estado) => Resultados.Any(r => r.Estado == estado);
    }
}
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class RelevanciaPrevia
{
    private const string PalabraDelReglamentoDerogado = "2023";
    private const int LongitudDelAnio = 4;
    private const string PrimerSemestre = "1";
    private const string SegundoSemestre = "2";

    private static readonly HashSet<string> TerminosPropiosDelCoordinador = new(StringComparer.Ordinal)
    {
        "estudiante", "estudiantes", "programa", "programas"
    };

    private readonly PoliticaAcceso _politicaAcceso;
    private readonly int _relevanciaMinima;

    public RelevanciaPrevia(PoliticaAcceso politicaAcceso, int relevanciaMinima)
    {
        _politicaAcceso = politicaAcceso;
        _relevanciaMinima = relevanciaMinima;
    }

    public bool PeriodoNoDisponible(ContextoUsuario contexto, string pregunta, ActivacionResumen activacion)
    {
        var palabras = TokenizadorTexto.Valores(pregunta);
        return (activacion.Candidata || EsConsultaDeDatosDeCoordinador(contexto, palabras)) && PideOtroPeriodo(palabras);
    }

    public bool DebeResponderSinInformacion(
        ContextoUsuario contexto,
        string pregunta,
        IReadOnlyList<SeccionDocumento> secciones,
        ActivacionResumen activacion)
    {
        var palabras = TokenizadorTexto.Valores(pregunta);
        if (activacion.Entrega || EsConsultaDeDatosDeCoordinador(contexto, palabras))
        {
            return false;
        }

        return !palabras.Contains(PalabraDelReglamentoDerogado) && !HaySeccionRelevante(pregunta, secciones);
    }

    private bool EsConsultaDeDatosDeCoordinador(ContextoUsuario contexto, IReadOnlyList<string> palabras)
    {
        if (contexto.Usuario.Rol != Rol.Coordinador)
        {
            return false;
        }

        var programas = _politicaAcceso.ProgramasAutorizados(contexto.Usuario, contexto.Directorio);
        return programas.Count > 0
            && (PideTerminosDeDatos(palabras) || MencionaEstudianteDeSusProgramas(contexto, palabras, programas));
    }

    private static bool PideTerminosDeDatos(IReadOnlyList<string> palabras) =>
        palabras.Any(TerminosPropiosDelCoordinador.Contains) || ActivadorResumenPropio.PideDatosAcademicos(palabras);

    private static bool MencionaEstudianteDeSusProgramas(
        ContextoUsuario contexto,
        IReadOnlyList<string> palabras,
        IReadOnlyList<string> programas)
    {
        var propios = contexto.Directorio.Estudiantes.Where(e => programas.Contains(e.ProgramaId)).Select(e => e.Id).ToHashSet();
        return DetectorTerceros.PersonasMencionadas(string.Join(' ', palabras), contexto.Directorio).Any(propios.Contains);
    }

    private static bool PideOtroPeriodo(IReadOnlyList<string> palabras) =>
        palabras.Zip(palabras.Skip(1)).Any(par => EsPeriodo(par.First, par.Second) && $"{par.First}-{par.Second}" != Textos.Periodo);

    private static bool EsPeriodo(string anio, string semestre) =>
        anio.Length == LongitudDelAnio && anio.All(char.IsAsciiDigit) && (semestre == PrimerSemestre || semestre == SegundoSemestre);

    private bool HaySeccionRelevante(string pregunta, IReadOnlyList<SeccionDocumento> secciones)
    {
        var raices = RaicesDeContenido.De(pregunta).ToHashSet(StringComparer.Ordinal);
        var minimo = Math.Min(_relevanciaMinima, (raices.Count + 1) / 2);
        return raices.Count > 0 && secciones.Any(seccion => RaicesDeContenido.De($"{seccion.Titulo} {seccion.Texto}").Count(raices.Contains) >= minimo);
    }
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Conocimiento;

public static class RaicesDeContenido
{
    private const int LongitudDeRaiz = 4;

    private static readonly HashSet<string> PalabrasVacias = new(StringComparer.Ordinal)
    {
        "cual", "cuales", "como", "cuando", "donde", "quien", "cuanto", "cuantos", "cuanta", "cuantas",
        "puedo", "tengo", "tiene", "tienen", "sobre", "para", "unos", "unas", "pero", "esta", "este", "esto",
        "dice", "dicen", "hacer", "hace", "debe", "puede", "pueden", "estoy", "estan", "dime", "dame", "muestra"
    };

    private static readonly HashSet<string> PalabrasGenericasDelCorpus = new(StringComparer.Ordinal)
    {
        "reglamento", "reglamentos", "documento", "documentos", "articulo", "articulos", "seccion", "secciones",
        "capitulo", "corporacion", "horizonte"
    };

    public static IEnumerable<string> De(string texto) =>
        NormalizadorTexto.Normalizar(texto)
            .Split(' ', StringSplitOptions.RemoveEmptyEntries)
            .Where(EsPalabraDeContenido)
            .Select(palabra => palabra[..LongitudDeRaiz])
            .Distinct(StringComparer.Ordinal);

    public static IReadOnlyCollection<string> DeApoyo(string texto) =>
        [.. De(texto).Concat(RaicesNumericas.De(texto))];

    private static bool EsPalabraDeContenido(string palabra) =>
        palabra.Length >= LongitudDeRaiz
        && !PalabrasVacias.Contains(palabra)
        && !PalabrasGenericasDelCorpus.Contains(palabra);
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Conocimiento;

public static partial class RaicesNumericas
{
    public static IEnumerable<string> De(string texto)
    {
        var plegado = ReferenciasASeccion.Quitar(TokenizadorTexto.Plegado(texto));
        var porcentajes = Porcentaje().Matches(plegado).Select(coincidencia => SinEspacios(coincidencia.Value)).ToList();
        var sinPorcentajes = Porcentaje().Replace(plegado, " ");
        var notas = FormaDeNota().Matches(sinPorcentajes).Select(coincidencia => coincidencia.Value);
        return porcentajes.Concat(notas).Distinct(StringComparer.Ordinal);
    }

    private static string SinEspacios(string valor) => valor.Replace(" ", string.Empty, StringComparison.Ordinal);

    [GeneratedRegex(@"(?<!\d)(?<!\d\.)\d+(?:\.\d{1,2})?\s*%")]
    private static partial Regex Porcentaje();

    [GeneratedRegex(@"(?<!\d)(?<!\d\.)\d\.\d{1,2}(?!\d)(?!\.\d)")]
    private static partial Regex FormaDeNota();
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Conocimiento;

public static class ConsultaDeRecuperacion
{
    public const int LongitudDeRaiz = 4;

    public static string DeTexto(string texto) =>
        string.Join(
            ' ',
            NormalizadorTexto.Normalizar(texto)
                .Split(' ', StringSplitOptions.RemoveEmptyEntries)
                .Where(palabra => palabra.Length >= LongitudDeRaiz)
                .Select(palabra => palabra[..LongitudDeRaiz])
                .Distinct());
}
using System.Text.RegularExpressions;

namespace TutorFlow.Core.Conocimiento;

public static partial class ReferenciasASeccion
{
    private const string Reemplazo = " ";

    public static string Quitar(string textoPlegado) => Referencia().Replace(textoPlegado, Reemplazo);

    [GeneratedRegex(@"(?<![a-z0-9])(?:secciones|seccion|articulos|articulo|art\.?|§)\s*\d+(?:\.\d+)*(?:\s*(?:,|y|e)\s*\d+(?:\.\d+)*)*")]
    private static partial Regex Referencia();
}
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class CitasDeRespuesta
{
    private const int MaximoCitasDeRespaldo = 2;

    private readonly int _apoyoMinimo;

    public CitasDeRespuesta(int apoyoMinimo)
    {
        _apoyoMinimo = apoyoMinimo;
    }

    public IReadOnlyList<Cita> EscritasConApoyo(string texto, IReadOnlyList<SeccionDocumento> entregadas, IReadOnlyCollection<Cita> reglasDeDatos)
    {
        var apoyadas = SeccionesConApoyo(texto, entregadas).Select(CitaDe).ToHashSet();
        return [.. ExtractorCitas.De(texto).Where(cita => apoyadas.Contains(cita) || reglasDeDatos.Contains(cita))];
    }

    public IReadOnlyList<Cita> Respaldo(string texto, IReadOnlyList<SeccionDocumento> entregadas) =>
        [.. SeccionesConApoyo(texto, entregadas).Take(MaximoCitasDeRespaldo).Select(CitaDe)];

    private IEnumerable<SeccionDocumento> SeccionesConApoyo(string texto, IReadOnlyList<SeccionDocumento> entregadas)
    {
        var raicesDeLaRespuesta = RaicesDeContenido.DeApoyo(ExtractorCitas.SinCitas(texto)).ToHashSet(StringComparer.Ordinal);
        return entregadas.Where(seccion => RaicesDeContenido.DeApoyo($"{seccion.Titulo} {seccion.Texto}").Count(raicesDeLaRespuesta.Contains) >= _apoyoMinimo);
    }

    private static Cita CitaDe(SeccionDocumento seccion) => new(seccion.Documento, seccion.Seccion);
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public static partial class ExtractorCitas
{
    private const string PrefijoArticulo = "Artículo";
    private const string PrefijoSeccion = "Sección";

    public static IReadOnlyList<Cita> De(string texto) =>
        CitaEnTexto().Matches(texto)
            .Select(coincidencia => new Cita(coincidencia.Groups["doc"].Value, Normalizar(coincidencia.Groups["sec"].Value)))
            .Distinct()
            .ToList();

    public static string SinCitas(string texto) =>
        CitaEnTexto().Replace(texto, " ");

    private static string Normalizar(string seccion)
    {
        var partes = seccion.Split(' ', 2, StringSplitOptions.RemoveEmptyEntries);
        return partes.Length < 2 ? seccion : $"{Prefijo(partes[0])} {partes[1].Trim()}";
    }

    private static string Prefijo(string palabra) =>
        palabra.StartsWith("Art", StringComparison.OrdinalIgnoreCase) ? PrefijoArticulo : PrefijoSeccion;

    [GeneratedRegex(@"(?<doc>[A-Za-z0-9_]+\.md)\s*·\s*(?<sec>Art[ií]culo\s+\d+|Secci[oó]n\s+\d+(?:\.\d+)?|Anexo)", RegexOptions.CultureInvariant)]
    private static partial Regex CitaEnTexto();
}
using System.Security.Cryptography;

namespace TutorFlow.Core.Asistente;

public sealed class ConfiguracionAsistente
{
    private const int BytesDelMarcadorAleatorio = 32;
    private const int TokensDeEntradaReservados = 8000;
    private const int TokensDeSalidaReservados = 2000;
    private const int MinimoPermitido = 1;

    public const int RelevanciaMinimaPorDefecto = 2;
    public const int ApoyoMinimoPorDefecto = 2;

    public ConfiguracionAsistente(
        PrecioModelo? precio,
        string? marcadorCanarioConfigurado,
        IReadOnlyCollection<string> codigosAsignatura,
        decimal? reservaPorPeticionUsd = null,
        int relevanciaMinima = RelevanciaMinimaPorDefecto,
        int apoyoMinimoRespaldo = ApoyoMinimoPorDefecto,
        IReadOnlyList<AsignaturaCatalogo>? catalogo = null)
    {
        Catalogo = catalogo is { Count: > 0 } ? catalogo : CatalogoAsignaturas.PorDefecto;
        Precio = precio;
        MarcadorCanario = string.IsNullOrWhiteSpace(marcadorCanarioConfigurado)
            ? Convert.ToHexString(RandomNumberGenerator.GetBytes(BytesDelMarcadorAleatorio))
            : marcadorCanarioConfigurado;
        CodigosAsignatura = codigosAsignatura;
        ReservaPorPeticionUsd = reservaPorPeticionUsd ?? ReservaPorDefecto(precio);
        RelevanciaMinima = Math.Max(MinimoPermitido, relevanciaMinima);
        ApoyoMinimoRespaldo = Math.Max(MinimoPermitido, apoyoMinimoRespaldo);
    }

    public PrecioModelo? Precio { get; }

    public string MarcadorCanario { get; }

    public IReadOnlyCollection<string> CodigosAsignatura { get; }

    public IReadOnlyList<AsignaturaCatalogo> Catalogo { get; }

    public decimal ReservaPorPeticionUsd { get; }

    public int RelevanciaMinima { get; }

    public int ApoyoMinimoRespaldo { get; }

    private static decimal ReservaPorDefecto(PrecioModelo? precio) =>
        CalculadoraCosto.Calcular(new UsoTokens(TokensDeEntradaReservados, TokensDeSalidaReservados), precio);
}
