158	        var contexto = new ContextoUsuario(usuario, sesion.Directorio);
159	        var entrada = await PrepararEntradaAsync(sesion, contexto, cancellationToken);
160	        var conversacion = new ConversacionLlm(_clienteLlm, new HerramientasAsistente(sesion.Api, _politicaAcceso), _limites, sesion.Uso);
161	        var resultado = await conversacion.EjecutarAsync(contexto, entrada, sesion.Registro, cancellationToken);
162	        return resultado.Estado switch
163	        {
164	            EstadoConversacion.IdAjeno => Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, sesion.Uso.Valor.Total, resultado.IdSolicitado),
165	            EstadoConversacion.LimiteHerramientas => NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
166	            EstadoConversacion.Rechazada => Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error),
167	            _ => Completar(sesion, resultado.Texto ?? string.Empty, entrada)
168	        };
169	    }
170	
171	    private async Task<EntradaConversacion> PrepararEntradaAsync(SesionPregunta sesion, ContextoUsuario contexto, CancellationToken cancellationToken)
172	    {
173	        var pregunta = sesion.Entrada.Pregunta;
174	        var resumen = await _lectorResumen.LeerAsync(contexto, sesion.Activacion, sesion.Api, sesion.Registro, cancellationToken);
175	        return new EntradaConversacion(pregunta, sesion.Secciones, resumen, ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario));
176	    }
177	
178	    private ResultadoPregunta Completar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
179	    {
180	        if (texto.Trim() == Textos.SinInformacion)
181	        {
182	            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
183	        }
184	
185	        foreach (var seccion in entrada.Secciones)
186	        {
187	            sesion.Registro.AgregarFuente($"{seccion.Titulo}. {seccion.Texto}");
188	        }
189	
190	        var directorio = sesion.Directorio;
191	        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, directorio);
192	        var candidatas = _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas);
193	        var verificada = _verificadorSalida.Verificar(sesion.Entrada.Usuario, texto, candidatas, autorizados, sesion.Registro.Fuentes, _baseConocimiento, directorio, Confidencial(sesion, entrada));
194	        return verificada.Resultado == ResultadoAuditoria.Respondida
195	            ? ResponderSiLasPerdidasSeRespaldan(sesion, verificada, entrada, autorizados)
196	            : Responder(sesion, verificada.Respuesta, verificada.Citas, verificada.Resultado);
197	    }
198	
199	    private ResultadoPregunta ResponderSiLasPerdidasSeRespaldan(
200	        SesionPregunta sesion,
201	        SalidaVerificada verificada,
202	        EntradaConversacion entrada,
203	        IReadOnlyCollection<string> autorizados) =>
204	        _afirmacionesDePerdida.SonVerificables(verificada.Respuesta, autorizados, sesion.Directorio, sesion.Registro.Resumenes)
205	            ? ResponderVerificada(sesion, verificada, entrada)
206	            : Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado);
207	
208	    private ResultadoPregunta ResponderVerificada(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
209	    {
210	        var citasDeTextoFijo = Textos.CitasDeTextoFijo(verificada.Respuesta);
211	        if (citasDeTextoFijo is not null)
212	        {
213	            return Responder(sesion, verificada.Respuesta, citasDeTextoFijo, verificada.Resultado);
214	        }
215	
216	        var citasDeDocumento = CitasDeDocumento(sesion, verificada, entrada);
217	        if (citasDeDocumento.Count == 0 && !sesion.Registro.UsoDatos)
218	        {
219	            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
220	        }
221	
222	        IReadOnlyList<Cita> citas = [.. citasDeDocumento.Concat(sesion.Registro.Citas).Distinct()];
223	        return Responder(sesion, verificada.Respuesta, citas, verificada.Resultado);
224	    }
225	
226	    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
227	    {
228	        var reglasAplicadas = _ordenDeReglas.Ordenar(sesion.Registro.Reglas, sesion.Entrada.Pregunta).Take(MaximoCitasDeReglasAplicadas);
229	        IReadOnlyList<Cita> escritasYReglas = [.. verificada.Citas.Concat(reglasAplicadas).Distinct()];
230	        return escritasYReglas.Count > 0
231	            ? escritasYReglas
232	            : _citasDeRespuesta.Respaldo(verificada.Respuesta, entrada.Secciones);
233	    }
234	
235	    private MaterialConfidencial Confidencial(SesionPregunta sesion, EntradaConversacion entrada) =>
236	        new(
237	            _configuracion.MarcadorCanario,
238	            [ConstructorPrompts.Instrucciones(entrada.PromptSistema), .. DescripcionesDeHerramientas(sesion.Entrada.Usuario.Rol)],
239	            HerramientasAsistente.NombresInternos);
240	
241	    private static IEnumerable<string> DescripcionesDeHerramientas(Rol rol) =>
242	        HerramientasAsistente.Definir(rol)
243	            .SelectMany(herramienta => herramienta.Parametros.Select(parametro => parametro.Descripcion).Prepend(herramienta.Descripcion));
244	
245	    private ResultadoPregunta Responder(
246	        SesionPregunta sesion,
247	        string texto,
248	        IReadOnlyList<Cita> citas,
249	        ResultadoAuditoria resultado,
250	        bool? usoDatos = null)
251	    {
252	        var respuesta = new RespuestaAsistente(
253	            texto,
254	            citas,
255	            usoDatos ?? sesion.Registro.UsoDatos,
256	            sesion.Uso.Valor.Total,
257	            CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio));
258	        Auditar(sesion, resultado, null, citas);
259	        return new ResultadoPregunta(TipoResultadoPregunta.Respondida, respuesta, resultado, null);
260	    }
261	
262	    private ResultadoPregunta Denegar(SesionPregunta sesion, MotivoDenegacion? motivo, int tokens, string? idSolicitado = null)
263	    {
264	        var costo = CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio);
265	        var citas = new[] { Textos.CitaNegativa() };
266	        var respuesta = new RespuestaAsistente(Textos.Negativa(sesion.Entrada.Usuario.Rol), citas, false, tokens, costo);
267	        Auditar(sesion, ResultadoAuditoria.Denegada, motivo, citas, idSolicitado);
268	        return new ResultadoPregunta(TipoResultadoPregunta.Denegada, respuesta, ResultadoAuditoria.Denegada, motivo);
269	    }
270	
271	    private ResultadoPregunta NoDisponible(SesionPregunta sesion, ResultadoAuditoria resultado)
272	    {
273	        Auditar(sesion, resultado, null, []);
274	        return new ResultadoPregunta(TipoResultadoPregunta.NoDisponible, null, resultado, null);
275	    }
276	
277	    private void Auditar(
278	        SesionPregunta sesion,
279	        ResultadoAuditoria resultado,
280	        MotivoDenegacion? motivo,
281	        IReadOnlyList<Cita> citas,
282	        string? idSolicitado = null)
283	    {
284	        var usuario = sesion.Entrada.Usuario;
285	        var pregunta = PreguntaAuditable(sesion);
286	        var costo = CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio);
287	        var registro = sesion.Registro;
288	        _auditor.Registrar(new EventoAuditoria(
289	            _auditor.AhoraUtc, sesion.CorrelationId, sesion.IpOrigen, usuario.Rol, usuario.Id, pregunta, resultado, motivo,
290	            registro.Estudiantes, registro.Recursos, citas, sesion.Uso.Valor.Total, costo,
291	            sesion.Cronometro.ElapsedMilliseconds, _configuracion.Precio is null)
292	        {
293	            DatosConsultados = registro.DatosConsultados,
294	            IdSolicitado = idSolicitado
295	        });
296	    }
297	
298	    private string PreguntaAuditable(SesionPregunta sesion)
299	    {
300	        var usuario = sesion.Entrada.Usuario;
301	        return _politicaAcceso.EvaluarIdentidad(usuario, sesion.Directorio).Permitido
302	            ? AuditorPeticiones.SanearPregunta(usuario, sesion.Entrada.Pregunta, sesion.Directorio)
303	            : _auditor.PreguntaSinIdentidad(sesion.Entrada.Pregunta);
304	    }
305	}
