 21	
 22	public sealed record ResultadoPregunta(
 23	    TipoResultadoPregunta Tipo,
 24	    RespuestaAsistente? Respuesta,
 25	    ResultadoAuditoria Auditoria,
 26	    MotivoDenegacion? Motivo);
 27	
 28	public sealed class PreguntarAsistente
 29	{
 30	    private const int MaximoCitasDeReglasAplicadas = 3;
 31	
 32	    private readonly IApiAcademica _apiAcademica;
 33	    private readonly IClienteLlm _clienteLlm;
 34	    private readonly IBaseConocimiento _baseConocimiento;
 35	    private readonly AuditorPeticiones _auditor;
 36	    private readonly PoliticaAcceso _politicaAcceso;
 37	    private readonly VerificadorSalida _verificadorSalida;
 38	    private readonly LimitesAsistente _limites;
 39	    private readonly ConfiguracionAsistente _configuracion;
 40	    private readonly PresupuestoDiario _presupuesto;
 41	    private readonly LectorResumenPropio _lectorResumen;
 42	    private readonly RelevanciaPrevia _relevancia;
 43	    private readonly CitasDeRespuesta _citasDeRespuesta;
 44	    private readonly OrdenDeReglasPorRelevancia _ordenDeReglas;
 45	    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
 46	
 47	    public PreguntarAsistente(
 48	        IApiAcademica apiAcademica,
 49	        IClienteLlm clienteLlm,
 50	        IBaseConocimiento baseConocimiento,
 51	        AuditorPeticiones auditor,
 52	        PoliticaAcceso politicaAcceso,
 53	        VerificadorSalida verificadorSalida,
 54	        LimitesAsistente limites,
 55	        ConfiguracionAsistente configuracion,
 56	        PresupuestoDiario presupuesto)
 57	    {
 58	        _apiAcademica = apiAcademica;
 59	        _clienteLlm = clienteLlm;
 60	        _baseConocimiento = baseConocimiento;
 61	        _auditor = auditor;
 62	        _politicaAcceso = politicaAcceso;
 63	        _verificadorSalida = verificadorSalida;
 64	        _limites = limites;
 65	        _configuracion = configuracion;
 66	        _presupuesto = presupuesto;
 67	        _lectorResumen = new LectorResumenPropio(politicaAcceso);
 68	        _relevancia = new RelevanciaPrevia(politicaAcceso, configuracion.RelevanciaMinima);
 69	        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
 70	        _ordenDeReglas = new OrdenDeReglasPorRelevancia(baseConocimiento);
 71	        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
 72	    }
 73	
 74	    public async Task<ResultadoPregunta> EjecutarAsync(
 75	        PreguntaEntrada entrada,
 76	        string ipOrigen,
 77	        string correlationId,
 78	        CancellationToken cancellationToken)
 79	    {
 80	        var presupuestoApi = TimeSpan.FromSeconds(_limites.PresupuestoApiAcademicaSegundos);
 81	        var api = new ApiAcademicaConPresupuesto(_apiAcademica, presupuestoApi);
 82	        var directorio = await ConstructorDirectorio.ConstruirAsync(entrada.Usuario, api, _configuracion.CodigosAsignatura, cancellationToken);
 83	        if (directorio is not null)
 84	        {
 85	            _auditor.RecordarPersonas(directorio);
 86	        }
 87	
 88	        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, api, directorio ?? ConstructorDirectorio.Vacio);
 89	        var decision = Autorizar(sesion);
 90	        return decision.Permitido
 91	            ? await ResponderSiEsRelevanteAsync(sesion, cancellationToken)
 92	            : Denegar(sesion, decision.Motivo, 0);
 93	    }
 94	
 95	    private async Task<ResultadoPregunta> ResponderSiEsRelevanteAsync(SesionPregunta sesion, CancellationToken cancellationToken)
 96	    {
 97	        var pregunta = sesion.Entrada.Pregunta;
 98	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
 99	        sesion.Secciones = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(pregunta), _limites.MaximoSeccionesRecuperadas);
100	        var activacion = ActivadorResumenPropio.Evaluar(contexto, pregunta, _configuracion.Catalogo);
101	        if (_relevancia.PeriodoNoDisponible(contexto, pregunta, activacion))
102	        {
103	            return SinInformacionPrevia(sesion);
104	        }
105	
106	        sesion.Activacion = await _lectorResumen.VerificarMatriculaAsync(contexto, activacion, sesion.Api, sesion.Registro, cancellationToken);
107	        return _relevancia.DebeResponderSinInformacion(contexto, pregunta, sesion.Secciones, sesion.Activacion)
108	            ? SinInformacionPrevia(sesion)
109	            : await ResponderConReservaAsync(sesion, cancellationToken);
110	    }
111	
112	    private ResultadoPregunta SinInformacionPrevia(SesionPregunta sesion) =>
113	        Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
114	
115	    private DecisionAcceso Autorizar(SesionPregunta sesion)
116	    {
117	        var identidad = _politicaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, sesion.Directorio);
118	        return identidad.Permitido
119	            ? _politicaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, sesion.Directorio)
120	            : identidad;
121	    }
122	
123	    private async Task<ResultadoPregunta> ResponderConReservaAsync(SesionPregunta sesion, CancellationToken cancellationToken)
124	    {
125	        var reserva = _configuracion.ReservaPorPeticionUsd;
126	        if (!_presupuesto.TryReservar(reserva))
127	        {
128	            return NoDisponible(sesion, ResultadoAuditoria.Error);
129	        }
130	
131	        try
132	        {
133	            return await ResponderConTimeoutAsync(sesion, cancellationToken);
134	        }
135	        finally
136	        {
137	            _presupuesto.Sustituir(reserva, CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio));
138	        }
139	    }
140	
141	    private async Task<ResultadoPregunta> ResponderConTimeoutAsync(SesionPregunta sesion, CancellationToken cancellationToken)
142	    {
143	        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
144	        limite.CancelAfter(TimeSpan.FromSeconds(_limites.TimeoutLlmSegundos));
145	        try
146	        {
147	            return await ResponderAsync(sesion, limite.Token);
148	        }
149	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
150	        {
151	            throw new DependenciaNoDisponibleException("El tiempo total de la petición se agotó.");
152	        }
153	    }
154	
155	    private async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken cancellationToken)
156	    {
157	        var usuario = sesion.Entrada.Usuario;
158	        var contexto = new ContextoUsuario(usuario, sesion.Directorio);
159	        var entrada = await PrepararEntradaAsync(sesion, contexto, cancellationToken);
160	        var conversacion = new ConversacionLlm(_clienteLlm, new HerramientasAsistente(sesion.Api, _politicaAcceso), _limites, sesion.Uso);
161	        var resultado = await conversacion.EjecutarAsync(contexto, entrada, sesion.Registro, cancellationToken);
162	        return resultado.Estado switch
163	        {
164	            EstadoConversacion.IdAjeno => Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, sesion.Uso.Valor.Total, resultado.IdSolicitado),
165	            EstadoConversacion.LimiteHerramientas => NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
166	            EstadoConversacion.Rechazada => Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error),
167	            _ => Completar(sesion, resultado.Texto ?? string.Empty, entrada)
168	        };
169	    }
170	
171	    private async Task<EntradaConversacion> PrepararEntradaAsync(SesionPregunta sesion, ContextoUsuario contexto, CancellationToken cancellationToken)
172	    {
173	        var pregunta = sesion.Entrada.Pregunta;
174	        var resumen = await _lectorResumen.LeerAsync(contexto, sesion.Activacion, sesion.Api, sesion.Registro, cancellationToken);
175	        return new EntradaConversacion(pregunta, sesion.Secciones, resumen, ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario));
176	    }
177	
178	    private ResultadoPregunta Completar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
179	    {
180	        if (texto.Trim() == Textos.SinInformacion)
181	        {
182	            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
183	        }
184	
185	        foreach (var seccion in entrada.Secciones)
186	        {
