  5	namespace TutorFlow.Infrastructure.Conocimiento;
  6	
  7	public sealed class BaseConocimientoEnMemoria : IBaseConocimiento
  8	{
  9	    private const int LongitudMaximaDeRaiz = ConsultaDeRecuperacion.LongitudDeRaiz;
 10	    private const int LongitudMinimaDeTermino = 3;
 11	    private const double ParametroK1 = 1.5;
 12	    private const double ParametroB = 0.75;
 13	    private const double PesoDelTitulo = 4.0;
 14	
 15	    private static readonly HashSet<string> PalabrasVacias = new(StringComparer.Ordinal)
 16	    {
 17	        "que", "cual", "cuales", "como", "cuando", "donde", "quien", "cuanto", "cuantos", "cuanta", "cuantas",
 18	        "hay", "puedo", "tengo", "tiene", "tienen", "sobre", "para", "por", "con", "del", "los", "las", "una",
 19	        "unos", "unas", "mis", "tus", "sus", "mas", "pero", "esta", "este", "esto", "ese", "esa", "son", "ser",
 20	        "dice", "dicen", "hacer", "hace", "debe", "puede", "pueden", "estoy", "estan", "dime", "dame", "muestra"
 21	    };
 22	
 23	    private readonly List<SeccionIndexada> _secciones;
 24	    private readonly Dictionary<string, int> _frecuenciaDeDocumento;
 25	    private readonly double _longitudPromedio;
 26	
 27	    public BaseConocimientoEnMemoria(IEnumerable<SeccionDocumento> secciones)
 28	    {
 29	        _secciones = secciones.Select(seccion => new SeccionIndexada(seccion, ExtraerRaices(seccion.Titulo + " " + seccion.Texto))).ToList();
 30	        _frecuenciaDeDocumento = _secciones
 31	            .SelectMany(indexada => indexada.Frecuencias.Keys)
 32	            .GroupBy(raiz => raiz)
 33	            .ToDictionary(grupo => grupo.Key, grupo => grupo.Count());
 34	        _longitudPromedio = _secciones.Count == 0 ? 1 : _secciones.Average(indexada => (double)indexada.Longitud);
 35	    }
 36	
 37	    public IReadOnlyList<SeccionDocumento> BuscarSecciones(string consulta, int maximo)
 38	    {
 39	        var terminos = ExpansionDeTerminos.Expandir(ExtraerRaices(consulta).Frecuencias.Keys);
 40	        return _secciones
 41	            .Select(indexada => (indexada.Seccion, Puntaje: Puntuar(indexada, terminos)))
 42	            .Where(par => par.Puntaje > 0)
 43	            .OrderByDescending(par => par.Puntaje)
 44	            .Take(maximo)
 45	            .Select(par => par.Seccion)
 46	            .ToList();
 47	    }
 48	
 49	    public bool ExisteCita(Cita cita) =>
 50	        _secciones.Any(indexada => indexada.Seccion.Documento == cita.Documento && indexada.Seccion.Seccion == cita.Seccion);
 51	
 52	    private static Raices ExtraerRaices(string texto)
 53	    {
 54	        var frecuencias = NormalizadorTexto.Normalizar(texto)
 55	            .Split(' ', StringSplitOptions.RemoveEmptyEntries)
 56	            .Where(palabra => palabra.Length >= LongitudMinimaDeTermino && !PalabrasVacias.Contains(palabra))
 57	            .Select(palabra => palabra.Length > LongitudMaximaDeRaiz ? palabra[..LongitudMaximaDeRaiz] : palabra)
 58	            .GroupBy(raiz => raiz)
 59	            .ToDictionary(grupo => grupo.Key, grupo => grupo.Count());
 60	        return new Raices(frecuencias);
 61	    }
 62	
 63	    private double Puntuar(SeccionIndexada indexada, IReadOnlyList<string> terminos)
 64	    {
 65	        var puntaje = terminos.Sum(termino => PuntajeDelTermino(indexada, termino));
 66	        return puntaje + PuntajeDeTitulo(indexada.Seccion, terminos);
 67	    }
 68	
 69	    private double PuntajeDelTermino(SeccionIndexada indexada, string termino)
 70	    {
 71	        if (!indexada.Frecuencias.TryGetValue(termino, out var frecuencia))
 72	        {
 73	            return 0;
 74	        }
 75	
 76	        var documentos = _frecuenciaDeDocumento[termino];
 77	        var idf = Math.Log(1 + (_secciones.Count - documentos + 0.5) / (documentos + 0.5));
 78	        var normalizacion = 1 - ParametroB + ParametroB * indexada.Longitud / _longitudPromedio;
 79	        return idf * frecuencia * (ParametroK1 + 1) / (frecuencia + ParametroK1 * normalizacion);
 80	    }
 81	
 82	    private static double PuntajeDeTitulo(SeccionDocumento seccion, IReadOnlyList<string> terminos)
 83	    {
 84	        var titulo = ExtraerRaices(seccion.Titulo).Frecuencias.Keys;
 85	        var coincidencias = terminos.Count(titulo.Contains);
 86	        return coincidencias * PesoDelTitulo;
 87	    }
 88	
 89	    private sealed record Raices(IReadOnlyDictionary<string, int> Frecuencias);
 90	
 91	    private sealed record SeccionIndexada(SeccionDocumento Seccion, Raices Raices)
 92	    {
 93	        public IReadOnlyDictionary<string, int> Frecuencias => Raices.Frecuencias;
 94	
 95	        public int Longitud => Raices.Frecuencias.Values.Sum();
 96	    }
 97	}

