178	internal sealed class AfirmacionesDePerdida
179	{
180	    private const int PalabrasDeNegacion = 2;
181	
182	    private static readonly HashSet<string> FormasDePerdida = new(StringComparer.Ordinal)
183	    {
184	        "perdi", "perdio", "perdiste", "perdieron", "perdido", "perdidos", "perdida", "perdidas"
185	    };
186	
187	    private static readonly HashSet<string> Negaciones = new(StringComparer.Ordinal)
188	    {
189	        "no", "ni", "sin", "ningun", "ninguna"
190	    };
191	
192	    private static readonly HashSet<string> Inasistencias = new(StringComparer.Ordinal)
193	    {
194	        "inasistencia", "inasistencias"
195	    };
196	
197	    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;
198	
199	    public AfirmacionesDePerdida(IReadOnlyList<AsignaturaCatalogo> catalogo)
200	    {
201	        _catalogo = catalogo;
202	    }
203	
204	    public bool SonVerificables(
205	        string respuesta,
206	        IReadOnlyCollection<string> idsAutorizados,
207	        DirectorioAcademico directorio,
208	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos) =>
209	        TramosDePersonas.Oraciones(respuesta)
210	            .SelectMany(oracion => TramosDePersonas.De(oracion, idsAutorizados, directorio))
211	            .All(tramo => TramoEsVerificable(tramo, resumenesLeidos));
212	
213	    private bool TramoEsVerificable(TramoDePersona tramo, IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
214	    {
215	        var nombradas = AsignaturasNombradas(tramo.Tokens);
216	        if (nombradas.Count == 0 || !HayPerdidaNoNegada(tramo.Tokens))
217	        {
218	            return true;
219	        }
220	
221	        return resumenesLeidos.TryGetValue(tramo.PersonaId, out var resumen)
222	            && ExigenciasPorAsignatura(tramo.Tokens, nombradas).All(exigencia => Cumple(exigencia, resumen));
223	    }
224	
225	    private static bool HayPerdidaNoNegada(IReadOnlyList<TokenTexto> tokens) =>
226	        Enumerable.Range(0, tokens.Count).Any(indice => FormasDePerdida.Contains(tokens[indice].Valor) && !EstaNegada(tokens, indice));
227	
228	    private static bool EstaNegada(IReadOnlyList<TokenTexto> tokens, int indice) =>
229	        Enumerable.Range(Math.Max(0, indice - PalabrasDeNegacion), Math.Min(PalabrasDeNegacion, indice))
230	            .Any(anterior => Negaciones.Contains(tokens[anterior].Valor));
231	
232	    private List<AsignaturaNombrada> AsignaturasNombradas(IReadOnlyList<TokenTexto> tokens) =>
233	        [.. _catalogo
234	            .Select(asignatura => new AsignaturaNombrada(AmbitoPersonal.Clave(asignatura.Codigo), PrimeraAparicion(tokens, asignatura)))
235	            .Where(nombrada => nombrada.Indice >= 0)
236	            .OrderBy(nombrada => nombrada.Indice)];
237	
238	    private static int PrimeraAparicion(IReadOnlyList<TokenTexto> tokens, AsignaturaCatalogo asignatura)
239	    {
240	        var apariciones = new[] { asignatura.Nombre, asignatura.Codigo }
241	            .Select(texto => TokenizadorTexto.BuscarSecuencia(tokens, TokenizadorTexto.Valores(texto)))
242	            .Where(indice => indice >= 0)
243	            .ToList();
244	        return apariciones.Count == 0 ? -1 : apariciones.Min();
245	    }
246	
247	    private static IEnumerable<ExigenciaDeAsignatura> ExigenciasPorAsignatura(
248	        IReadOnlyList<TokenTexto> tokens,
249	        IReadOnlyList<AsignaturaNombrada> nombradas)
250	    {
251	        var inasistencias = Enumerable.Range(0, tokens.Count).Where(indice => Inasistencias.Contains(tokens[indice].Valor)).ToList();
252	        var antesDeLaPrimera = inasistencias.Any(indice => indice < nombradas[0].Indice);
253	        return nombradas.Select((nombrada, posicion) =>
254	        {
255	            var hasta = posicion + 1 < nombradas.Count ? nombradas[posicion + 1].Indice : int.MaxValue;
256	            var porInasistencia = antesDeLaPrimera || inasistencias.Any(indice => indice >= nombrada.Indice && indice < hasta);
257	            return new ExigenciaDeAsignatura(nombrada.Clave, porInasistencia);
258	        });
259	    }
260	
261	    private static bool Cumple(ExigenciaDeAsignatura exigencia, ResumenEstudiante resumen)
262	    {
263	        var resultado = resumen.Asignaturas.FirstOrDefault(r => AmbitoPersonal.Clave(r.Asignatura.Codigo) == exigencia.Clave);
264	        return resultado is not null
265	            && (exigencia.PorInasistencia
266	                ? resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia
267	                : resultado.Estado is EstadoAsignatura.Perdida or EstadoAsignatura.PerdidaPorInasistencia);
268	    }
269	
270	    private sealed record AsignaturaNombrada(string Clave, int Indice);
271	
272	    private sealed record ExigenciaDeAsignatura(string Clave, bool PorInasistencia);
273	}

