     8	    private const string SeparadoresFinales = ".,";
     9	
    10	    public static bool HayValorNoRespaldado(string respuesta, IReadOnlyCollection<string> textosFuente)
    11	    {
    12	        var respaldados = textosFuente
    13	            .SelectMany(texto => Numero().Matches(texto).Select(coincidencia => coincidencia.Value))
    14	            .ToHashSet(StringComparer.Ordinal);
    15	        return ValoresMonetarios(respuesta).Any(valor => !respaldados.Contains(valor));
    16	    }
    17	
    18	    private static IEnumerable<string> ValoresMonetarios(string respuesta)
    19	    {
    20	        var plegada = TokenizadorTexto.Plegado(respuesta);
    21	        return new[] { ConSimbolo(), ConMoneda(), ConMonedaDespues(), ConSeparadorDeMiles() }
    22	            .SelectMany(patron => patron.Matches(plegada))
    23	            .Select(coincidencia => coincidencia.Groups["n"].Value.TrimEnd(SeparadoresFinales.ToCharArray()))
    24	            .Distinct(StringComparer.Ordinal);
    25	    }
    26	
